    fixtureSourceValues.length > 0
      ? executeQuery<FixtureBySourceRefRow>(
          client,
          `SELECT f.fixture_id::text                  AS "canonicalId",
                  f.source_ref                        AS "sourceRef",
                  f.competition_id::text              AS "competitionId",
