                      FILTER (WHERE ft.team_id IS NOT NULL),
                    ARRAY[]::text[]
                  )                                   AS "teamIds"
             FROM fixture f
             LEFT JOIN venue v ON v.venue_id = f.venue_id
             LEFT JOIN fixture_team ft ON ft.fixture_id = f.fixture_id
            WHERE f.source_ref = ANY($1::text[])
            GROUP BY
