      });
    } else if (
      fixture.sourceId &&
      !(fixture.context && isIncomparableFixtureSourceIdentifier(fixture.sourceId))
    ) {
      resolvedFixture = resolveFixtureBySourceId(
        fixturePath,
        submitted,
        fixture.sourceId,
        fixture.context ?? null,
        fixtureTeamOutcomes,
        fixtureBySourceRef,
        fixtureByCanonicalId,
        competitionId,
        seasonName,
