    async resolvePublishedConflict(account, reference, request) {
      if (!canReviewBatch(account)) throw new BatchForbiddenError();
      const batch = await repository.findBatchByReference(reference);
      if (!batch) throw new BatchForbiddenError();
      try {
        await repository.resolvePublishedConflict({
          batchId: batch.batchId,
          actorId: account.accountId,
          itemOrdinal: request.itemOrdinal,
          existingDeliveryId: request.existingDeliveryId,
          decision: request.decision,
          reason: request.reason,
        });
      } catch (error) {
        if (error instanceof BatchPublishedConflictResolutionError) {
          throw new BatchConflictError(error.message);
        }
        throw error;
      }
      const current = await repository.findBatchById(batch.batchId);
      if (!current) throw new Error('Resolved batch could not be reloaded.');
      return { data: await status(current) };
    },

    async mapReference(account, reference, request) {
      const batch = await findAuthorizedBatch(account, reference);
      let afterOrdinal: number | undefined;
      let selection:
        { entityType: BatchReferenceEntityType; canonicalId: string; label: string } | undefined;

      for (;;) {
        const items = await repository.listBatchItems(batch.batchId, {
          ...(afterOrdinal === undefined ? {} : { afterOrdinal }),
          limit: 1000,
        });
        for (const item of items) {
          if (item.ordinal !== request.itemOrdinal) continue;
          for (const outcome of storedOutcomes(item.resolvedReferences)) {
            if (outcome.referencePath !== request.referencePath) {
              continue;
            }
            const candidate = outcome.candidates.find(
              (value) =>
                !value.outOfScope &&
                (outcome.entityType !== 'competition' ||
                  value.canonicalId === batch.competitionId) &&
                candidateReference(
                  reference,
                  item.ordinal,
                  outcome.referencePath,
                  value.canonicalId,
                ) === request.candidateReference,
            );
            if (candidate) {
              selection = {
                entityType: outcome.entityType,
                canonicalId: candidate.canonicalId,
                label: candidate.label,
              };
              break;
            }
          }
          if (selection) break;
        }
        if (selection || items.length < 1000) break;
        afterOrdinal = items.at(-1)!.ordinal;
      }

      if (!selection) {
        throw new BatchConflictError(
          'The selected candidate is stale or is not available for this reference.',
        );
      }

      try {
        const decision = await repository.queueReferenceMapping({
          decisionReference: randomUUID(),
          batchId: batch.batchId,
          actorId: account.accountId,
          itemOrdinal: request.itemOrdinal,
          referencePath: request.referencePath,
          entityType: selection.entityType,
          candidateId: selection.canonicalId,
          candidateLabel: selection.label,
          decisionKey: request.decisionKey,
        });
        return {
          data: {
            batchReference: reference,
            decisionReference: decision.decisionReference,
            status: decision.state === 'applied' ? 'applied' : 'queued',
            statusUrl: `${API_BASE_PATH}/batches/${reference}`,
            submittedAt: decision.decidedAt,
          },
        };
      } catch (error) {
        if (error instanceof BatchReferenceMappingConflictError) {
          throw new BatchConflictError(error.message);
        }
        throw error;
      }
    },

    async createCanonicalFixture(account, reference, request) {
      if (!canReviewBatch(account)) throw new BatchForbiddenError();
      const batch = await repository.findBatchByReference(reference);
      if (!batch) throw new BatchForbiddenError();
      const items = await repository.listBatchItems(batch.batchId, { limit: 1000 });
      const item = items.find((value) => value.ordinal === request.itemOrdinal);
      const evidence =
        item &&
        storedOutcomes(item.resolvedReferences).find(
          (value) =>
            value.referencePath === request.referencePath && value.entityType === 'fixture',
        );
      const submitted = evidence?.submittedReference as
        | {
            sourceId?: string;
            context?: { date?: string; teams?: { context?: { name?: string } }[] };
            proposal?: Record<string, unknown>;
            season?: { context?: { name?: string } };
          }
        | undefined;
      const proposal = fixtureProposalSchema.safeParse(submitted?.proposal);
      const teams = submitted?.context?.teams?.map((team) => team.context?.name).filter(Boolean);
      if (
        !item ||
        batch.packageVersion !== FIXTURE_PROPOSAL_CONTRACT_VERSION ||
        !submitted?.sourceId ||
        !submitted.context?.date ||
        !submitted.season?.context?.name ||
        !proposal.success ||
        teams?.length !== 2
      ) {
        throw new BatchConflictError('A complete version 1.1 fixture proposal is required.');
      }
      try {
        const decision = await repository.createCanonicalFixtureAndQueueMapping({
          batchId: batch.batchId,
          batchReference: reference,
          competitionId: batch.competitionId,
          actorId: account.accountId,
          itemOrdinal: item.ordinal,
          referencePath: request.referencePath,
          decisionKey: request.decisionKey,
          sourceRef: submitted.sourceId.split(':', 3)[2]!,
          season: submitted.season.context.name,
          startDate: submitted.context.date,
          teamNames: teams as string[],
          proposal: proposal.data,
        });
        return {
          data: {
            batchReference: reference,
            decisionReference: decision.decisionReference,
            status: decision.state === 'applied' ? 'applied' : 'queued',
            statusUrl: `${API_BASE_PATH}/batches/${reference}`,
            submittedAt: decision.decidedAt,
          },
        };
      } catch (error) {
        if (error instanceof BatchReferenceMappingConflictError)
          throw new BatchConflictError(error.message);
        throw error;
      }
    },
  };
}
