  const match = /^stored-object:([0-9a-f-]{36})$/i.exec(sourceUri);
  if (!match)
    throw new PermanentBatchFailure(
      'INVALID_SOURCE_REFERENCE',
      'Batch source reference is invalid.',
    );
  return match[1]!;
}

