        sourceRef: miscountedSourceRef,
      });
      miscountedFixtureId = miscountedIngestion.fixtureId;
    } catch (error) {
      await client.query('ROLLBACK').catch(() => undefined);
      client.release();
      client = undefined;
      await pool.end();
      pool = undefined;
