    if (!firstMember) await reader.expect(',');
    firstMember = false;
    const key = await reader.jsonString();
    await reader.expect(':');
    if (key !== 'fixtures') {
      await reader.valueRaw();
      continue;
    }

    await reader.expect('[');
    let fixtureIndex = 0;
