  seasonSchema,
} from '../public-read';

describe('public read contracts', () => {
  test('requires and preserves innings scorecard context', () => {
    const base = {
      statisticId: 'stat-team',
      fixtureId: '9',
      scope: 'innings' as const,
      statisticCode: 'team_total' as const,
      inningsId: '30',
      inningsOrdinal: 0,
      competitorId: '20',
      competitorName: 'Joburg Super Kings',
      sourceEventCount: 0,
