      participantId: '101',
      participantName: 'BB McCullum',
      scope: 'career',
      statisticCode: 'participant_career',
      appearances: 1,
      fixtureCount: 1,
      sourceEventCount: 60,
      batting: {
        innings: 1,
        runsScored: 116,
        ballsFaced: 56,
        dismissals: 0,
        notOuts: 1,
        battingAverage: null,
        fours: 12,
        sixes: 8,
        fifties: 0,
        hundreds: 1,
        highestScore: 116,
        highestScoreNotOut: true,
        strikeRate: 207.14,
      },
      bowling: {
        innings: 1,
        runsConceded: 24,
        wides: 2,
