        legalBallsBowled: 18,
        wicketsTaken: 2,
        bowlingAverage: 12,
        bowlingStrikeRate: 9,
        bestBowling: { wicketsTaken: 2, runsConceded: 24 },
        fourWicketHauls: 0,
