import request from 'supertest';
import { describe, expect, test, vi } from 'vitest';

import type { VerifyAccessToken } from '../../src/auth/supabase-auth';
import type { ParticipantAggregatesService } from '../../src/modules/statistics/participant-aggregates.service';
import { createTestApp } from '../test-app';

const careerAggregates: ParticipantAggregates = {
  participantId: '101',
  participantName: 'BB McCullum',
  status: 'complete',
  scope: { superOversIncluded: false },
  warnings: [],
  statistics: [
    {
      statisticId: 'stat_career',
      participantId: '101',
      participantName: 'BB McCullum',
      scope: 'career',
      statisticCode: 'participant_career',
      appearances: 1,
      fixtureCount: 1,
      sourceEventCount: 60,
      batting: {
        innings: 1,
        runsScored: 116,
        ballsFaced: 56,
        dismissals: 0,
        notOuts: 1,
        battingAverage: null,
        fours: 12,
        sixes: 8,
        fifties: 0,
        hundreds: 1,
        highestScore: 116,
        highestScoreNotOut: true,
        strikeRate: 207.14,
      },
      bowling: {
        innings: 1,
        runsConceded: 24,
        wides: 2,
        noBalls: 1,
        legalBallsBowled: 18,
        wicketsTaken: 2,
        bowlingAverage: 12,
        bowlingStrikeRate: 9,
        bestBowling: { wicketsTaken: 2, runsConceded: 24 },
        fourWicketHauls: 0,
        fiveWicketHauls: 0,
        ballsPerOver: 6,
