// ---------------------------------------------------------------------------
// Participant aggregates (season, competition and career)
//
// Issue #285. The catalogue in docs/requirements/sport-domain-definition.md Â§7
// names season aggregates (grouped by competition and season) and career
// aggregates (grouped across all seasons). Competition-wide is required by the
// issue but is not named as a level in Â§7; it is the same rollup grouped by
// competition alone, and Â§7 needs extending to record it.
//
// Every level excludes super-over innings, per Â§7 and issue #104, and groups by
// person identifier rather than display name: Â§10 records that names are not
// identity.
// ---------------------------------------------------------------------------

export const participantAggregateBattingSchema = z.object({
