    expect(aggregates.status).toBe('complete');
    expect(aggregates.scope).toEqual({ superOversIncluded: false });
    expect(aggregates.statistics.map((statistic) => statistic.scope)).toEqual([
      'season',
      'competition',
      'career',
    ]);

