import { z } from 'zod';

import {
  apiDateSchema,
  apiIdentifierSchema,
  createCollectionResponseSchema,
  createResourceResponseSchema,
  MAX_PAGE_LIMIT,
  paginationQuerySchema,
} from './api';

const filterTextSchema = z.string().trim().min(1);

// Basic exports are synchronous and complete. Issue #467 found the export read a
// single page of 100 and discarded the cursor, so 85% of imported innings were
// exported short without any indication. An export now follows the event
// collection's cursor at the public maximum page size until it is exhausted.
export const FIXTURE_EVENT_EXPORT_PAGE_SIZE = MAX_PAGE_LIMIT;

// The bound that keeps a synchronous export finite. Reaching it fails the whole
// export with EXPORT_TOO_LARGE rather than returning a short file. The largest
// fixture in the imported corpus has 346 accepted events, so a filtered or
// single-fixture export does not approach it.
export const FIXTURE_EVENT_EXPORT_MAX_EVENTS = 5_000;

export const competitionSchema = z.object({
  competitionId: apiIdentifierSchema,
  name: z.string().min(1),
});

export const seasonSchema = z.object({
  seasonId: apiIdentifierSchema,
  competitionId: apiIdentifierSchema,
  competitionName: z.string().min(1),
  label: z.string().min(1),
});

export const fixtureCompetitorSummarySchema = z.object({
  competitorId: apiIdentifierSchema,
  name: z.string().min(1),
});

> import {
  competitionListQuerySchema,
  competitorListQuerySchema,
  FIXTURE_EVENT_EXPORT_MAX_EVENTS,
  fixtureEventExportQuerySchema,
  fixtureEventListQuerySchema,
  fixtureListQuerySchema,
  fixtureStatisticEventExportQuerySchema,
  participantFixtureListQuerySchema,
  participantListQuerySchema,
  seasonListQuerySchema,
} from '@sport-analytics/contracts';
import type { FixtureStatistic, PublicEvent } from 
'@sport-analytics/contracts';
import type { Request, RequestHandler, Response } from 'express';
import type { z } from 'zod';

import type { FixtureStatisticsService } from 
'../statistics/fixture-statistics.service';
import {
  fixtureEventExportFilename,
  normalizeExportEvent,
  serializeFixtureEventsCsv,
  type FixtureEventExportFilenameFilters,
} from './fixture-event-export';
import { FixtureEventExportTooLargeError, PublicReadInputError } from 
'./public-read.errors';
import type { PublicReadService } from './public-read.service';

type AsyncHandler = (request: Request, response: Response) => 
Promise<void>;

function wrapPublicHandler(handler: AsyncHandler): RequestHandler {
  return (request, response, next) => {
    void handler(request, response).catch((error) => {
      if (error instanceof PublicReadInputError) {
        response.status(400).json({
          error: {
            code: error.code,
            message: error.message,
          },
        });
        return;
      }

      if (error instanceof FixtureEventExportTooLargeError) {
        response.status(422).json({
          error: {
            code: error.code,
            message: error.message,
          },
        });
        return;
      }

      // Any other failure, including one on a later export page, reaches 
the
      // error handler before a file has been sent, so it can never 
produce a
      // short export.
      next(error);
    });
  };
}

function parseQuery<S extends z.ZodTypeAny>(
  schema: S,
  request: Request,
  response: Response,
): z.output<S> | undefined {
  const result = schema.safeParse(request.query);
  if (result.success) {
    return result.data;
  }

  response.status(400).json({
    error: {
      code: 'VALIDATION_FAILED',
      message: 'The request is invalid.',
      details: result.error.issues.map((issue) => ({
        code: 'INVALID_FIELD',
        message: issue.message,
        ...(issue.path.length > 0
          ? {
              field: issue.path.join('.'),
            }
          : {}),
      })),
    },
  });

  return undefined;
}
function getPathParameter(request: Request, name: string): string {
  const value = request.params[name];

  if (value === undefined) {
    throw new Error(`Expected route parameter "${name}" was not 
provided.`);
  }

  return value;
}

function sendNotFound(response: Response, resource: string): void {
  response.status(404).json({
    error: {
      code: 'NOT_FOUND',
      message: `${resource} not found.`,
    },
  });
}

// The trace filters a statistic corresponds to, used only to name its 
export
// file the same way the filtered export of that trace is named.
function traceFilenameFilters(statistic: FixtureStatistic): 
FixtureEventExportFilenameFilters {
  return statistic.scope === 'innings'
    ? { inningsId: statistic.inningsId, competitorId: 
statistic.competitorId }
    : { participantId: statistic.participantId };
}

function sameEventOrder(events: PublicEvent[], eventIds: string[]): 
boolean {
  return (
    events.length === eventIds.length &&
    events.every((event, index) => event.eventId === eventIds[index])
  );
}

export function createPublicReadController(service: PublicReadService) {
  return {
    listCompetitions: wrapPublicHandler(async (request, response) => {
      const query = parseQuery(competitionListQuerySchema, request, 
response);

      if (!query) {
        return;
      }

      response.status(200).json(await service.listCompetitions(query));
    }),

    getCompetition: wrapPublicHandler(async (request, response) => {
      const competition = await 
service.getCompetition(getPathParameter(request, 'competitionId'));

      if (!competition) {
        sendNotFound(response, 'Competition');
        return;
      }

      response.status(200).json({
        data: competition,
      });
    }),

