/**
 * Calculation-trace exports: exactly the events a trace displays, so the 
file
 * reproduces the figure on the page it was downloaded from.
 */
export function createFixtureStatisticEventExportController(
  service: Pick<PublicReadService, 'exportFixtureEvents'>,
  fixtureStatisticsService: Pick<FixtureStatisticsService, 
'getFixtureStatistic'>,
) {
  /**
   * The statistic's own contributing events, resolved through the 
derivation
   * the trace page renders, then read in full through the paging export.
   * Returns null when a response has already been sent.
   */
  async function readStatisticTraceEvents(
    request: Request,
    response: Response,
  ): Promise<{ fixtureId: string; events: PublicEvent[]; statistic: 
FixtureStatistic } | null> {
    const query = parseQuery(fixtureStatisticEventExportQuerySchema, 
request, response);
    if (!query) {
      return null;
    }

    const fixtureId = getPathParameter(request, 'fixtureId');
    const statistic = await fixtureStatisticsService.getFixtureStatistic(
      fixtureId,
      getPathParameter(request, 'statisticId'),
      { includeContributors: true },
    );
    if (!statistic) {
      sendNotFound(response, 'Fixture statistic');
      return null;
    }

    const tracedEventIds = (statistic.contributingEvents ?? 
[]).map((event) => event.eventId);
    if (tracedEventIds.length > FIXTURE_EVENT_EXPORT_MAX_EVENTS) {
      throw new 
FixtureEventExportTooLargeError(FIXTURE_EVENT_EXPORT_MAX_EVENTS);
    }

    const events =
      tracedEventIds.length === 0
        ? []
        : await service.exportFixtureEvents(fixtureId, { eventIds: 
tracedEventIds });
    if (!events) {
      sendNotFound(response, 'Fixture');
      return null;
    }

    // The trace and the event rows are read separately, so a correction
    // accepted between the two reads could make them differ. The file must
    // then not be sent: it would silently disagree with the trace it 
names.
    if (!sameEventOrder(events, tracedEventIds)) {
      response.status(409).json({
        error: {
          code: 'EXPORT_TRACE_CHANGED',
          message:
            'The accepted events changed while this export was prepared, 
so it no longer matches the calculation trace. Reload the trace and try 
again.',
        },
      });
      return null;
    }

    return { fixtureId, events, statistic };
  }

  return {
    exportFixtureStatisticEventsJson: wrapPublicHandler(async (request, 
response) => {
      const trace = await readStatisticTraceEvents(request, response);

      if (!trace) {
        return;
      }

      response
        .status(200)
        .type('application/json')
        .json({ data: trace.events.map(normalizeExportEvent) });
    }),

    exportFixtureStatisticEventsCsv: wrapPublicHandler(async (request, 
response) => {
      const trace = await readStatisticTraceEvents(request, response);

      if (!trace) {
        return;
      }

      response
        .status(200)
        .type('text/csv')
        .attachment(
          fixtureEventExportFilename(trace.fixtureId, 
traceFilenameFilters(trace.statistic)),
        )
        .send(serializeFixtureEventsCsv(trace.events));
    }),
  };
}

