+            WHEN 'most_wickets' THEN wickets::numeric
+            WHEN 'most_fours' THEN fours::numeric
+            WHEN 'most_sixes' THEN sixes::numeric
+            WHEN 'highest_batting_average' THEN runs_scored::numeric / NULLIF(dismissals, 0)
