      const mediaType = mediaTypes.find((type) => type.toLowerCase() === contentType);
      if (!mediaType) {
        problems.push(
          `status ${status} content type '${contentType || '(none)'}' is not documented; documented: ${mediaTypes.join(', ')}`,
